  var faq = '';
  for(var f = 0; f < L.faq.length; f++) faq += '<h3>' + L.faq[f][0] + '</h3><p>' + L.faq[f][1] + '</p>';
  var html = '<h1>' + L.h1 + '</h1><p>' + L.p1 + '</p><p>' + L.p2 + '</p>'
    + '<h2>' + L.howH + '</h2>' + list('ol', L.steps)
