export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (request.method === 'GET' && url.pathname === '/') {
      try {
        if (env.ANALYTICS) {
          env.ANALYTICS.writeDataPoint({
            blobs: [request.headers.get('cf-ipcountry') || 'XX'],
            indexes: ['pageview'],
            doubles: [1]
          });
        }
        if (env.DB) {
          await ensureStatsTable(env, getDateParts(request.cf && request.cf.timezone));
        }
      } catch (_) {}
      return new Response(mainPage(), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Accept-CH': 'Sec-CH-Prefers-Color-Scheme', 'Critical-CH': 'Sec-CH-Prefers-Color-Scheme' } });
    }

    if (request.method === 'GET' && url.pathname === '/stats') {
      try {
        if (env.DB) {
          const parts = clientDateParts(url) || getDateParts(request.cf && request.cf.timezone);
          await ensureStatsTable(env, parts);
          if (url.searchParams.get('record') === '1') {
            await env.DB.prepare(
              `INSERT INTO site_views (day, views) VALUES (?1, 1)
               ON CONFLICT(day) DO UPDATE SET views = views + 1`
            ).bind(parts.today).run();
          }
          const { today, monthPrefix, yearPrefix } = parts;
          const row = await env.DB.prepare(`
            SELECT
              COALESCE(SUM(CASE WHEN day = ?1 THEN views ELSE 0 END), 0) AS today,
              COALESCE(SUM(CASE WHEN day LIKE ?2 THEN views ELSE 0 END), 0) AS month,
              COALESCE(SUM(CASE WHEN day LIKE ?3 THEN views ELSE 0 END), 0) AS year,
              COALESCE(SUM(views), 0) AS total
            FROM site_views
          `).bind(today, monthPrefix, yearPrefix).first();

          return new Response(JSON.stringify({
            today: Number(row?.today || 0),
            month: Number(row?.month || 0),
            year:  Number(row?.year  || 0),
            all:   Number(row?.total || 0)
          }), {
            headers: {
              'Content-Type': 'application/json',
              'Cache-Control': 'no-store, no-cache, must-revalidate',
              'Access-Control-Allow-Origin': '*'
            }
          });
        }

        const ae = await queryAnalyticsEngine(env);
        if (ae) {
          return new Response(JSON.stringify(ae), {
            headers: {
              'Content-Type': 'application/json',
              'Cache-Control': 'no-store, no-cache, must-revalidate',
              'Access-Control-Allow-Origin': '*'
            }
          });
        }
        return new Response(JSON.stringify({ error: 'Stats unavailable' }), { status: 503, headers: { 'Content-Type': 'application/json' } });
      } catch (e) {
        return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } });
      }
    }

    if (request.method === 'GET' && url.pathname === '/manifest.webmanifest') {
      const darkManifest = (request.headers.get('sec-ch-prefers-color-scheme') || '').indexOf('dark') !== -1;
      return new Response(JSON.stringify(darkManifest ? PWA_MANIFEST_DARK : PWA_MANIFEST), { headers: { 'Content-Type': 'application/manifest+json; charset=utf-8', 'Cache-Control': 'public, max-age=600', 'Accept-CH': 'Sec-CH-Prefers-Color-Scheme', 'Critical-CH': 'Sec-CH-Prefers-Color-Scheme', 'Vary': 'Sec-CH-Prefers-Color-Scheme' } });
    }

    if (request.method === 'GET' && url.pathname === '/sw.js') {
      return new Response(PWA_SW, { headers: { 'Content-Type': 'text/javascript; charset=utf-8', 'Cache-Control': 'no-cache' } });
    }

    if (request.method === 'GET' && url.pathname === '/og-image.png') {
      return pwaIconResponse(OG_IMAGE_B64);
    }
    if (request.method === 'GET' && PWA_ICONS[url.pathname]) {
      return pwaIconResponse(PWA_ICONS[url.pathname]);
    }

    if (request.method === 'GET' && url.pathname === '/.well-known/assetlinks.json') {
      return new Response(ASSETLINKS_JSON, { headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'public, max-age=3600' } });
    }

    if (request.method === 'GET' && url.pathname === '/robots.txt') {
      return new Response(ROBOTS_TXT, { headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'public, max-age=86400' } });
    }

    if (request.method === 'GET' && url.pathname === '/sitemap.xml') {
      return new Response(SITEMAP_XML, { headers: { 'Content-Type': 'application/xml; charset=utf-8', 'Cache-Control': 'public, max-age=86400' } });
    }

    if (request.method === 'GET' && url.pathname === '/llms.txt') {
      return new Response(LLMS_TXT, { headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'public, max-age=86400' } });
    }

    if (request.method === 'GET' && url.pathname === '/27a3602eb8241245538754f8236dc95d.txt') {
      return new Response('27a3602eb8241245538754f8236dc95d', { headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'public, max-age=86400' } });
    }

    if (request.method === 'GET' && url.pathname === '/google630f8769faf46d65.html') {
      return new Response('google-site-verification: google630f8769faf46d65.html', { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=86400' } });
    }

    if (request.method === 'GET' && url.pathname === '/about') {
      return new Response(aboutPage(), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=120' } });
    }

    if (request.method === 'GET' && GUIDE_PAGES[url.pathname]) {
      return new Response(guidePage(GUIDE_PAGES[url.pathname]), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=120' } });
    }

    if (request.method === 'GET') return new Response(mainPage(), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Accept-CH': 'Sec-CH-Prefers-Color-Scheme', 'Critical-CH': 'Sec-CH-Prefers-Color-Scheme' } });

    if (request.method === 'POST' && url.pathname === '/process') {
      try {
        const fd = await request.formData();
        const action = fd.get('action');

        if (action === 'transcribe') {
          const file = fd.get('file');
          if (!file) return new Response('No file', { status: 400 });
          const gf = new FormData();
          gf.append('file', file, file.name || 'audio.wav');
          const wm = fd.get('model');
          gf.append('model', wm === 'whisper-large-v3-turbo' ? 'whisper-large-v3-turbo' : 'whisper-large-v3');
          gf.append('response_format', 'text');
          gf.append('language', 'en');
          gf.append('prompt', 'English university lecture: statistics, pharmacology, chemistry, biochemistry. Write numbers as digits.');
          const gr = await fetch('https://api.groq.com/openai/v1/audio/transcriptions', {
            method: 'POST', headers: { 'Authorization': `Bearer ${env.GROQ_API_KEY}` }, body: gf
          });
          const grText = await gr.text();
          if (!gr.ok) return new Response('Groq error: ' + grText, { status: 500 });
          return new Response(grText.trim(), { headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
        }

        return new Response('Invalid action', { status: 400 });
      } catch (e) {
        return new Response('Error: ' + e.message, { status: 500 });
      }
    }
    return new Response('Not Found', { status: 404 });
  }
};

